    public Object parseTransaction(Map<String, Object> transaction, Map<String, Object> currency)
    {
        //
        //  fetchDeposits
        //     {
        //         "time": "1721641082163",
        //         "coin": "TRXUSDT", // todo how to parse it?
        //         "coinName": "TRXUSDT",
        //         "address": "TBA6CypYJizwA9XdC7Ubgc5F1bxrQ7SqPt",
        //         "quantity": "86.00000000000000000000",
        //         "status": 4,
        //         "statusCode": "4",
        //         "txId": "0970c14da4d7412295fa7b21c03a08da319e746a0d59ef14462a74183d118da4"
        //     }
        //
        // fetchWithdrawals
        //     {
        //         "time": "1723545505366",
        //         "id": "W611267400947572736",
        //         "coin": "USDT",
        //         "coinId": "USDT",
        //         "coinName": "USDT",
        //         "address": "TQbkBMnWnJNGTAUpFS4kvv4NRLzUAnGAes",
        //         "quantity": "2.00000000",
        //         "arriveQuantity": "2.00000000",
        //         "txId": "f83f94e7d2e81fbec98c66c25d6615872cc2d426145629b6cf22e5e0a0753715",
        //         "addressUrl": "TQbkBMnWnJNGTAUpFS4kvv4NRLzUAnGAes",
        //         "feeCoinId": "USDT",
        //         "feeCoinName": "USDT",
        //         "fee": "1.00000000",
        //         "remark": "",
        //         "platform": ""
        //     }
        //
        // withdraw
        //     {
        //         "success": true,
        //         "id": "0",
        //         "orderId": "W611267400947572736",
        //         "accountId": "1732885739589466115"
        //     }
        //
        String id = this.safeString2(transaction, "id", "orderId");
        String address = this.safeString(transaction, "address");
        String status = this.safeString(transaction, "status"); // for fetchDeposits
        if (java.util.Objects.equals(status, null))
        {
            Boolean success = (Boolean) this.safeBool(transaction, "success", false); // for withdraw
            if (java.util.Objects.equals(success, true))
            {
                status = "ok";
            } else
            {
                String addressUrl = this.safeString(transaction, "addressUrl"); // for fetchWithdrawals
                if (!java.util.Objects.equals(addressUrl, null))
                {
                    status = "ok";
                }
            }
        }
        String txid = this.safeString(transaction, "txId");
        String coin = this.safeString(transaction, "coin");
        String code = this.safeCurrencyCode(coin, currency);
        Long timestamp = this.safeInteger(transaction, "time");
        Double amount = this.safeNumber(transaction, "quantity", (Object) null);
        Double feeCost = this.safeNumber(transaction, "fee", (Object) null);
        Map<String, Object> fee = null;
        if (!java.util.Objects.equals(feeCost, null))
        {
            fee = Helpers.newMap(
                "cost", feeCost,
                "currency", code
            );
        }
        return Helpers.newMap(
            "info", transaction,
            "id", id,
            "txid", txid,
            "timestamp", timestamp,
            "datetime", this.iso8601(timestamp),
            "network", null,
            "address", address,
            "addressTo", null,
            "addressFrom", null,
            "tag", null,
            "tagTo", null,
            "tagFrom", null,
            "type", null,
            "amount", amount,
            "currency", code,
            "status", this.parseTransactionStatus(status),
            "updated", null,
            "internal", null,
            "comment", null,
            "fee", fee
        );
    }

    public String parseTransactionStatus(String status)
    {
        Map<String, Object> statuses = new HashMap<String, Object>() {{
            put( "1", "pending" );
            put( "2", "pending" );
            put( "3", "failed" );
            put( "4", "ok" );
            put( "5", "pending" );
            put( "6", "ok" );
            put( "7", "failed" );
            put( "8", "cancelled" );
            put( "9", "failed" );
            put( "10", "failed" );
            put( "successful", "ok" );
            put( "success", "ok" );
        }};
        return this.safeString(statuses, status, status);
    }

