            {
                (this.loadMarkets(false, new HashMap<String, Object>() {{}})).join();
            }
            Map<String, Object> response = (this.privateGetApiV1AccountVipInfo(parameters)).join();
            //
            //     {
            //         "code": 0,
            //         "vipLevel": "0",
            //         "tradeVol30Day": "67",
            //         "totalAssetBal": "0",
            //         "data": [
